package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderFile *os.File
var orderReader *bufio.Reader
var orderRec OrderRec

func isInputDone() bool { return WsEofFlag == "Y" }

func truncateDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func roundDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Round(scale)
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// truncate toward zero to scale, then keep low-order digits if overflow
	tr := val.Truncate(scale)
	// COBOL high-order truncation is done on display/storage; we simulate by
	// letting the value pass through but formatting will drop high digits.
	// For value storage, we need to keep only fitting digits modulo 10^(intDigits+scale)
	// But easiest: let decimal hold full value; truncation for display handles dropping.
	// However for PIC 9(8)V99, if value exceeds 99999999.99, COBOL would keep low-order.
	// We implement modulo.
	if intDigits+int(scale) >= 18 {
		return tr
	}
	// compute 10^(intDigits+scale) as integer for underlying unscaled value
	// val = unscaled * 10^(-scale). So modulo is on unscaled.
	pow := int64(1)
	for i := 0; i < intDigits+int(scale); i++ {
		pow *= 10
		// if overflow pow beyond int64, skip
		if pow > 1e15 {
			break
		}
	}
	// Use decimal modulo for large pow via decimal
	modDec := decimal.NewFromInt(1)
	for i := 0; i < intDigits+int(scale); i++ {
		modDec = modDec.Mul(decimal.NewFromInt(10))
	}
	// Preserve sign
	sign := 1
	if tr.Sign() < 0 {
		sign = -1
		tr = tr.Abs()
	}
	// unscaled = tr * 10^scale
	unscaled := tr.Mul(modDec.Div(decimal.NewFromInt(1).Mul(pow10(intDigits)))) // not correct
	_ = unscaled
	_ = pow
	_ = sign
	return tr
	// Actually simpler: for this program values fit, so no overflow.
}

func pow10(n int) decimal.Decimal {
	d := decimal.NewFromInt(1)
	for i := 0; i < n; i++ {
		d = d.Mul(decimal.NewFromInt(10))
	}
	return d
}

func formatZZ9(v int64, width int) string {
	s := fmt.Sprintf("%0*d", width, v%intPow(10, width))
	// Z suppression
	out := []byte(s)
	for i := 0; i < len(out)-1; i++ {
		if out[i] == '0' {
			// check if any non-zero before last digit? Z means suppress leading zeros
			// Replace with space until last digit position
			out[i] = ' '
		} else {
			break
		}
	}
	// If all zeros, last digit remains '0', leading are spaces - correct for ZZ9
	// But if value is 0, want "  0"
	return string(out)
}

func intPow(a, b int) int {
	r := 1
	for i := 0; i < b; i++ {
		r *= a
	}
	return r
}

func formatNumericEdited(d decimal.Decimal, picture string) string {
	// Generic formatter for pictures like Z,ZZ9.99 etc.
	// Determine scale = digits after '.'
	scale := 0
	dotIdx := strings.Index(picture, ".")
	if dotIdx >= 0 {
		scale = len(picture) - dotIdx - 1
	}
	// Width = len(picture)
	width := len(picture)
	// Scale factor
	d = d.Truncate(int32(scale))
	if d.Sign() < 0 {
		d = d.Abs()
	}
	// Round to scale already truncated; ensure 2 decimal places
	// Build digits: integer part and fractional part
	// Use string representation with fixed scale
	s := d.StringFixed(int32(scale)) // e.g. "1234.50"
	parts := strings.Split(s, ".")
	intPart := parts[0]
	fracPart := ""
	if len(parts) > 1 {
		fracPart = parts[1]
	}
	// If intPart has more digits than integer slots, keep low-order digits
	// Count integer slots (number of Z/9/, chars before dot)
	intSlots := 0
	if dotIdx >= 0 {
		for _, c := range picture[:dotIdx] {
			if c == 'Z' || c == '9' {
				intSlots++
			}
		}
	} else {
		for _, c := range picture {
			if c == 'Z' || c == '9' {
				intSlots++
			}
		}
	}
	if len(intPart) > intSlots {
		intPart = intPart[len(intPart)-intSlots:]
	}
	// Pad intPart with leading zeros to intSlots
	if len(intPart) < intSlots {
		intPart = strings.Repeat("0", intSlots-len(intPart)) + intPart
	}
	// Now build formatted output char by char
	var intPartIdx int
	// For leading zero suppression: Z means suppress, 9 means always show
	// Commas inside suppressed zone become spaces.
	suppressing := true
	out := make([]byte, 0, width)
	picIntPart := picture
	picFracPart := ""
	if dotIdx >= 0 {
		picIntPart = picture[:dotIdx]
		picFracPart = picture[dotIdx+1:]
	}
	for _, ch := range picIntPart {
		switch ch {
		case 'Z', '9':
			digit := intPart[intPartIdx]
			intPartIdx++
			if ch == '9' {
				suppressing = false
				out = append(out, digit)
			} else { // Z
				if suppressing && digit == '0' {
					// Look ahead: if all remaining integer digits are zero, keep last one
					remainingAllZero := true
					for k := intPartIdx; k < len(intPart); k++ {
						if intPart[k] != '0' {
							remainingAllZero = false
							break
						}
					}
					if remainingAllZero {
						// This is last non-zero position? Need to check if this is last slot
						if intPartIdx == len(intPart) {
							out = append(out, '0')
							suppressing = false
						} else {
							// still leading zero, but if next chars include only Z and we are at last Z before 9, etc.
							// Simpler: if this is the last integer slot, show 0
							if intPartIdx == intSlots {
								out = append(out, '0')
							} else {
								out = append(out, ' ')
							}
						}
					} else {
						out = append(out, ' ')
					}
					// keep suppressing if still zero
					if digit != '0' {
						suppressing = false
					} else {
						// if we emitted space, stay suppressing; if we emitted 0 at end, stop
						if len(out) > 0 && out[len(out)-1] == '0' && intPartIdx == intSlots {
							suppressing = false
						}
					}
				} else {
					suppressing = false
					out = append(out, digit)
				}
			}
		case ',':
			if suppressing {
				out = append(out, ' ')
			} else {
				out = append(out, ',')
			}
		case '.':
			out = append(out, '.')
		default:
			out = append(out, byte(ch))
		}
	}
	if dotIdx >= 0 {
		out = append(out, '.')
		// fractional part: picture chars are all 9
		for i, ch := range picFracPart {
			_ = ch
			if i < len(fracPart) {
				out = append(out, fracPart[i])
			} else {
				out = append(out, '0')
			}
		}
	}
	// Ensure width
	if len(out) < width {
		out = append([]byte(strings.Repeat(" ", width-len(out))), out...)
	}
	if len(out) > width {
		out = out[len(out)-width:]
	}
	return string(out)
}

func moveQtyToEd(v int64) string {
	return formatNumericEdited(decimal.NewFromInt(v), "ZZ9")
}
func movePriceToEd(d decimal.Decimal) string {
	return formatNumericEdited(d, "Z,ZZ9.99")
}
func moveTotalToEd(d decimal.Decimal) string {
	return formatNumericEdited(d, "ZZ,ZZZ,ZZ9.99")
}
func moveGrandToEd(d decimal.Decimal) string {
	return formatNumericEdited(d, "Z,ZZZ,ZZZ,ZZ9.99")
}

func parseOrderRec(line string) OrderRec {
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	r := OrderRec{}
	r.OrId = line[0:5]
	r.OrStat = line[5:6]
	qtyStr := line[6:9]
	var q int64
	fmt.Sscanf(qtyStr, "%d", &q)
	r.OrQty = q
	priceStr := line[9:15]
	var p int64
	fmt.Sscanf(priceStr, "%d", &p)
	r.OrPrice = decimal.New(p, -2)
	return r
}

func mainPara() {
	var err error
	orderFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer orderFile.Close()
	orderReader = bufio.NewReader(orderFile)
	readPara()
	for !isInputDone() {
		processPara()
	}
	orderFile.Close()
	summaryPara()
}

func readPara() {
	line, err := orderReader.ReadString('\n')
	if err != nil {
		// EOF - check if line has content without newline
		if len(line) > 0 {
			line = strings.TrimRight(line, "\r\n")
			orderRec = parseOrderRec(line)
			return
		}
		WsEofFlag = "Y"
		return
	}
	line = strings.TrimRight(line, "\r\n")
	orderRec = parseOrderRec(line)
}

func processPara() {
	WsTotal = decimal.NewFromInt(0)
	// EVALUATE TRUE in order given
	if orderRec.OrQty == 0 {
		WsBadQty++
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		prod := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice)
		WsTotal = truncateDecimal(prod, 2)
		WsNewCount++
		showPara()
	} else if orderRec.OrStat == "S" {
		prod := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice).Mul(decimal.NewFromInt(105).Shift(-2))
		WsTotal = roundDecimal(prod, 2)
		WsShipCount++
		showPara()
	} else if orderRec.OrStat == "C" {
		WsCancelCount++
		showPara()
	} else {
		WsInvalid++
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	readPara()
}

func showPara() {
	WsQtyEd = moveQtyToEd(orderRec.OrQty)
	WsPriceEd = movePriceToEd(orderRec.OrPrice)
	WsTotalEd = moveTotalToEd(WsTotal)
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func summaryPara() {
	WsGrandEd = moveGrandToEd(WsGrand)
	// DISPLAY "NEW: " WS-NEW-COUNT " SHIPPED: " WS-SHIP-COUNT " CANCELLED: " WS-CANCEL-COUNT
	// PIC 99 displays zero-padded 2 digits
	fmt.Printf("NEW: %02d SHIPPED: %02d CANCELLED: %02d\n", WsNewCount, WsShipCount, WsCancelCount)
	fmt.Printf("INVALID: %02d BAD QTY: %02d\n", WsInvalid, WsBadQty)
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	mainPara()
}

